-- BEGIN FILE: 20261022_p04_lockdown_anon_access.sql
-- ---------------------------------------------------------------
-- ==============================================================================
-- MIGRATION: 20261022_p04_lockdown_anon_access.sql
-- Fixes audit findings P04-01 (quiz PINs readable) and P04-02 (anonymous writes).
--
-- CLASSIFICATION : PERMISSIONS CHANGE. No rows are changed or deleted.
--                  Reversible with 20261022_p04_lockdown_anon_access_rollback.sql
-- SCOPE          : ONLY the eight ces_* tables. This Supabase project is SHARED with
--                  another application of the same church (sermons), so this file deliberately does NOT
--                  touch other tables, schema-wide grants or ALTER DEFAULT PRIVILEGES.
-- WHY IT IS SAFE : the CES app reads/writes ces_* data only through server code that
--                  uses the service_role key (which bypasses RLS and keeps its grants).
--                  The browser/cookie clients are used only for staff sign-in.
-- ==============================================================================

BEGIN;

-- P04-01: the public could read ces_quizzes.session_pin (policy allowed any open quiz).
-- The existing "Staff can manage quizzes" (FOR ALL ... is_ces_staff()) policy remains.
DROP POLICY IF EXISTS "Public can view open quizzes" ON ces_quizzes;

-- P04-02: anyone could insert students / attendance directly, bypassing server validation.
DROP POLICY IF EXISTS "Anyone can register (insert student)" ON ces_students;
DROP POLICY IF EXISTS "Anyone can insert attendance" ON ces_attendance_records;

-- Defence in depth: remove the blanket GRANT ALL that earlier migrations gave to the
-- public-facing roles. With no privileges, these roles cannot reach the tables even if
-- a permissive policy is added by mistake later.
REVOKE ALL ON TABLE
  ces_staff_profiles,
  ces_semesters,
  ces_students,
  ces_quizzes,
  ces_quiz_questions,
  ces_student_assessments,
  ces_attendance_records,
  ces_certificates
FROM anon, authenticated;

-- The server (service_role) keeps full access (explicit, so nothing depends on defaults).
GRANT ALL ON TABLE
  ces_staff_profiles,
  ces_semesters,
  ces_students,
  ces_quizzes,
  ces_quiz_questions,
  ces_student_assessments,
  ces_attendance_records,
  ces_certificates
TO service_role;

COMMIT;



-- ---------------------------------------------------------------
-- BEGIN FILE: 20261023_p03_matric_counter.sql
-- ---------------------------------------------------------------
-- ==============================================================================
-- MIGRATION: 20261023_p03_matric_counter.sql
-- Fixes audit finding P03-01 (matric number race / reuse).
--
-- CLASSIFICATION : ADDITIVE. Creates one table and one function. No existing rows change.
--                  Reversible with 20261023_p03_matric_counter_rollback.sql
-- SCOPE          : CES objects only (shared Supabase project: sermons app untouched).
-- RULE           : sequence restarts every month (per YY + month), shared by both cohorts,
--                  never reused after a student is deleted. e.g. 26H801, 26H802 ...
-- ==============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS ces_matric_counters (
  counter_key TEXT PRIMARY KEY,          -- e.g. '26H8' = year 26, August
  last_seq    INTEGER NOT NULL DEFAULT 0
);

ALTER TABLE ces_matric_counters ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE ces_matric_counters FROM anon, authenticated;
GRANT ALL ON TABLE ces_matric_counters TO service_role;

-- Seed from existing students so numbering continues where it stopped
-- (soft-deleted rows included, so their numbers are never handed out again).
INSERT INTO ces_matric_counters (counter_key, last_seq)
SELECT
  substr(matric_no, 9, 3) || (ascii(substr(matric_no, 11, 1)) - 64)::text AS counter_key,
  max(substr(matric_no, 12 + length((ascii(substr(matric_no, 11, 1)) - 64)::text))::int) AS last_seq
FROM ces_students
WHERE matric_no ~ '^CES/ILR/[0-9]{2}[A-L][0-9]+$'
  AND substr(matric_no, 12 + length((ascii(substr(matric_no, 11, 1)) - 64)::text)) ~ '^[0-9]+$'
GROUP BY 1
ON CONFLICT (counter_key) DO UPDATE SET last_seq = GREATEST(ces_matric_counters.last_seq, EXCLUDED.last_seq);

-- Atomic: one statement increments and returns, so two simultaneous registrations
-- can never receive the same number.
CREATE OR REPLACE FUNCTION ces_next_matric_seq(p_year INT, p_month INT)
RETURNS INT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_key TEXT;
  v_seq INT;
BEGIN
  IF p_month < 1 OR p_month > 12 THEN
    RAISE EXCEPTION 'month must be 1-12';
  END IF;
  v_key := lpad((p_year % 100)::text, 2, '0') || chr(64 + p_month) || p_month::text;
  INSERT INTO ces_matric_counters (counter_key, last_seq)
  VALUES (v_key, 1)
  ON CONFLICT (counter_key) DO UPDATE SET last_seq = ces_matric_counters.last_seq + 1
  RETURNING last_seq INTO v_seq;
  RETURN v_seq;
END;
$$;

REVOKE ALL ON FUNCTION ces_next_matric_seq(INT, INT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION ces_next_matric_seq(INT, INT) TO service_role;

COMMIT;



-- ---------------------------------------------------------------
-- BEGIN FILE: 20261024_p04_class_codes_and_rate_limits.sql
-- ---------------------------------------------------------------
-- ==============================================================================
-- MIGRATION: 20261024_p04_class_codes_and_rate_limits.sql
-- Fixes audit findings P04-03 (attendance forgeable) and P04-05 (no rate limiting).
--
-- CLASSIFICATION : ADDITIVE. Creates two tables and one function. No existing rows change.
--                  Reversible with 20261024_p04_class_codes_and_rate_limits_rollback.sql
-- SCOPE          : CES objects only (project is SHARED with the sermons app: untouched).
-- ==============================================================================

BEGIN;

-- Per-class attendance codes. The teacher opens a class and reads the code out;
-- students need it to check in. Rows are created closed by the server.
CREATE TABLE IF NOT EXISTS ces_class_codes (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  semester_id UUID NOT NULL REFERENCES ces_semesters(id) ON DELETE CASCADE,
  course_name TEXT NOT NULL,
  code        TEXT NOT NULL,
  is_open     BOOLEAN NOT NULL DEFAULT FALSE,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (semester_id, course_name)
);

-- Fixed-window rate limit counters (key = e.g. 'att:ip:1.2.3.4').
CREATE TABLE IF NOT EXISTS ces_rate_limits (
  key          TEXT PRIMARY KEY,
  window_start TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  hits         INTEGER NOT NULL DEFAULT 0
);

ALTER TABLE ces_class_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE ces_rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE ces_class_codes, ces_rate_limits FROM anon, authenticated;
GRANT ALL ON TABLE ces_class_codes, ces_rate_limits TO service_role;

-- Atomic: records one attempt and returns TRUE while the caller is within the limit.
CREATE OR REPLACE FUNCTION ces_rate_limit_hit(p_key TEXT, p_max INT, p_window_seconds INT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_hits INT;
BEGIN
  INSERT INTO ces_rate_limits AS rl (key, window_start, hits)
  VALUES (p_key, NOW(), 1)
  ON CONFLICT (key) DO UPDATE SET
    hits = CASE
      WHEN rl.window_start < NOW() - make_interval(secs => p_window_seconds) THEN 1
      ELSE rl.hits + 1
    END,
    window_start = CASE
      WHEN rl.window_start < NOW() - make_interval(secs => p_window_seconds) THEN NOW()
      ELSE rl.window_start
    END
  RETURNING rl.hits INTO v_hits;

  -- Housekeeping: occasionally drop counters idle for over a day.
  IF random() < 0.01 THEN
    DELETE FROM ces_rate_limits WHERE window_start < NOW() - INTERVAL '1 day';
  END IF;

  RETURN v_hits <= p_max;
END;
$$;

REVOKE ALL ON FUNCTION ces_rate_limit_hit(TEXT, INT, INT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION ces_rate_limit_hit(TEXT, INT, INT) TO service_role;

COMMIT;



-- ---------------------------------------------------------------
-- BEGIN FILE: 20261025_p04_audit_log_and_score_guard.sql
-- ---------------------------------------------------------------
-- ==============================================================================
-- MIGRATION: 20261025_p04_audit_log_and_score_guard.sql
-- Fixes audit findings P04-10 (no audit trail, scores could exceed the quiz maximum)
-- and P04-16 (is_ces_staff() had no fixed search_path).
--
-- CLASSIFICATION : ADDITIVE + one safety check. No existing rows are changed or deleted.
--                  Reversible with 20261025_p04_audit_log_and_score_guard_rollback.sql
-- SCOPE          : CES objects only (project is SHARED with the sermons app: untouched).
-- IF IT FAILS    : the whole script runs in one transaction, so a failure changes nothing.
-- ==============================================================================

BEGIN;

-- 0. Safety check: refuse to continue if any stored score already exceeds its quiz maximum.
--    (If this fires, nothing has been changed. Fix or review those rows first.)
DO $$
DECLARE
  bad_count INT;
BEGIN
  SELECT count(*) INTO bad_count
  FROM ces_student_assessments a
  JOIN ces_quizzes q ON q.id = a.quiz_id
  WHERE a.score > q.max_score;
  IF bad_count > 0 THEN
    RAISE EXCEPTION 'Aborting: % assessment row(s) have a score above the quiz maximum. Review them before applying this migration.', bad_count;
  END IF;
END $$;

-- 1. Append-only audit log of staff changes to scores and attendance.
--    No foreign keys on purpose: history must survive if a student or staff member is later removed.
CREATE TABLE IF NOT EXISTS ces_audit_log (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  actor_id     UUID,
  actor_email  TEXT,
  action       TEXT NOT NULL,          -- e.g. 'score_override', 'attendance_override'
  student_id   UUID,
  target_table TEXT NOT NULL,
  target_id    UUID,
  old_value    JSONB,
  new_value    JSONB,
  reason       TEXT
);

CREATE INDEX IF NOT EXISTS idx_ces_audit_log_created ON ces_audit_log(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ces_audit_log_student ON ces_audit_log(student_id);

ALTER TABLE ces_audit_log ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE ces_audit_log FROM anon, authenticated;
-- The server may add and read entries, never change or delete them.
GRANT SELECT, INSERT ON TABLE ces_audit_log TO service_role;

-- Even a role that holds UPDATE/DELETE rights cannot rewrite history through normal SQL.
CREATE OR REPLACE FUNCTION ces_audit_log_immutable()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  RAISE EXCEPTION 'ces_audit_log is append-only';
END;
$$;

DROP TRIGGER IF EXISTS trg_ces_audit_log_no_change ON ces_audit_log;
CREATE TRIGGER trg_ces_audit_log_no_change
  BEFORE UPDATE OR DELETE ON ces_audit_log
  FOR EACH ROW EXECUTE FUNCTION ces_audit_log_immutable();

DROP TRIGGER IF EXISTS trg_ces_audit_log_no_truncate ON ces_audit_log;
CREATE TRIGGER trg_ces_audit_log_no_truncate
  BEFORE TRUNCATE ON ces_audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION ces_audit_log_immutable();

-- 2. A score can never exceed the maximum of its quiz, whatever the application sends.
CREATE OR REPLACE FUNCTION ces_enforce_score_range()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  v_max NUMERIC;
BEGIN
  SELECT max_score INTO v_max FROM ces_quizzes WHERE id = NEW.quiz_id;
  IF v_max IS NULL THEN
    RAISE EXCEPTION 'Quiz % not found', NEW.quiz_id;
  END IF;
  IF NEW.score < 0 OR NEW.score > v_max THEN
    RAISE EXCEPTION 'Score % is outside the allowed range 0-% for this assessment', NEW.score, v_max
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ces_score_range ON ces_student_assessments;
CREATE TRIGGER trg_ces_score_range
  BEFORE INSERT OR UPDATE OF score, quiz_id ON ces_student_assessments
  FOR EACH ROW EXECUTE FUNCTION ces_enforce_score_range();

-- 3. P04-16: pin the search_path of the staff-check function used by the RLS policies.
ALTER FUNCTION is_ces_staff() SET search_path = public, pg_temp;

COMMIT;



-- ---------------------------------------------------------------
-- BEGIN FILE: 20261027_p03_integrity_consent_email.sql
-- ---------------------------------------------------------------
-- ==============================================================================
-- MIGRATION: 20261027_p03_integrity_consent_email.sql
-- Fixes audit findings P03-12 (cascading deletes), P03-10 (consent not stored)
-- and P03-07 (no unique email, no record of email delivery).
--
-- CLASSIFICATION : STRUCTURE CHANGE. Adds columns and a unique index, and changes three
--                  foreign keys. No existing rows are changed or deleted.
--                  Reversible with 20261027_p03_integrity_consent_email_rollback.sql
-- SCOPE          : CES tables only (project is SHARED with the sermons app: untouched).
-- IF IT FAILS    : one transaction, so a failure changes nothing.
-- ==============================================================================

BEGIN;

-- 0. Safety check: refuse to continue if two live students share an email within one semester.
--    (A returning student in a LATER semester may reuse their email; that stays allowed.)
DO $$
DECLARE
  dup_count INT;
BEGIN
  SELECT count(*) INTO dup_count FROM (
    SELECT lower(trim(email_address)), semester_id
    FROM ces_students
    WHERE is_deleted = false
    GROUP BY 1, 2
    HAVING count(*) > 1
  ) d;
  IF dup_count > 0 THEN
    RAISE EXCEPTION 'Aborting: % email address(es) are used by more than one student in the same semester. Resolve them first.', dup_count;
  END IF;
END $$;

-- 1. P03-12: academic records must never vanish because a student row is deleted.
--    Replace ON DELETE CASCADE with ON DELETE RESTRICT on the three student_id foreign keys
--    (same constraint names, looked up dynamically). Use the existing is_deleted soft delete
--    / status instead of removing students.
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT c.conrelid::regclass AS tbl, c.conname
    FROM pg_constraint c
    WHERE c.contype = 'f'
      AND c.confrelid = 'ces_students'::regclass
      AND c.conrelid IN (
        'ces_student_assessments'::regclass,
        'ces_attendance_records'::regclass,
        'ces_certificates'::regclass
      )
  LOOP
    EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', r.tbl, r.conname);
    EXECUTE format(
      'ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY (student_id) REFERENCES ces_students(id) ON DELETE RESTRICT',
      r.tbl, r.conname
    );
  END LOOP;
END $$;

-- 2. P03-10: remember when each student agreed to the data-protection notice, and which version.
--    Existing students stay NULL (consent was given before it was recorded).
ALTER TABLE ces_students
  ADD COLUMN IF NOT EXISTS consent_at      TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS consent_version TEXT;

-- 3. P03-07: record whether the welcome email (matric number + manual) went out.
--    Existing students get 'unknown'; new registrations start as 'pending'.
ALTER TABLE ces_students
  ADD COLUMN IF NOT EXISTS email_status  TEXT NOT NULL DEFAULT 'unknown'
    CHECK (email_status IN ('unknown', 'pending', 'sent', 'failed', 'not_configured')),
  ADD COLUMN IF NOT EXISTS email_sent_at TIMESTAMPTZ;
ALTER TABLE ces_students ALTER COLUMN email_status SET DEFAULT 'pending';

-- 4. P03-07: one registration per email address per semester (case-insensitive).
CREATE UNIQUE INDEX IF NOT EXISTS uq_ces_students_email_semester
  ON ces_students (lower(trim(email_address)), semester_id)
  WHERE is_deleted = false;

COMMIT;

